() => {
  const all = Array.from(document.querySelectorAll('*'));
  const el = all.find(e => e.children.length === 0 && e.textContent && e.textContent.trim().startsWith('自动更新'));
  if (!el) return null;
  const badge = el.closest('span,div,em,b,strong') || el;
  const cs = getComputedStyle(badge);
  const parentCs = badge.parentElement ? getComputedStyle(badge.parentElement) : null;
  return {
    text: badge.textContent.trim() + (el.nextSibling ? '' : ''),
    badgeColor: cs.color,
    badgeBg: cs.backgroundColor,
    badgeBorder: cs.borderColor,
    parentColor: parentCs ? parentCs.color : null,
    parentBg: parentCs ? parentCs.backgroundColor : null,
    cls: badge.className,
    parentCls: badge.parentElement ? badge.parentElement.className : null
  };
}

() => {
  const h = Array.from(document.querySelectorAll('h3')).find(e => e.textContent.includes('各机构本年投放金额排名'));
  if (!h) return null;
  const card = h.closest('div[class*="rounded"], section, article') || h.parentElement.parentElement;
  const svg = card.querySelector('svg');
  if (!svg) return {bars: -1};
  const rects = svg.querySelectorAll('rect');
  const paths = svg.querySelectorAll('path');
  // echarts bars are usually <path> or <rect>; count visible bar-like shapes
  let barCount = 0;
  svg.querySelectorAll('path, rect').forEach(el => {
    const bb = el.getBBox ? el.getBBox() : null;
    if (bb && bb.width > 0 && bb.height > 0 && bb.width < 30 && bb.height > 2) barCount++;
  });
  return {rects: rects.length, paths: paths.length, barLike: barCount};
}

() => {
