() => {
  try {
    const raw = localStorage.getItem('analytics-store');
    const parsed = JSON.parse(raw);
    const state = parsed.state || parsed;
    const widgets = state.dashboardWidgets || [];
    return widgets.map(w => ({id: w.id, title: w.title, ds: w.dataSourceId, hasSql: !!w.sourceSql, dataLen: Array.isArray(w.data) ? w.data.length : null, lastAutoUpdatedAt: w.lastAutoUpdatedAt || null}));
  } catch (e) { return {error: String(e)}; }
}

() => {
  const raw = JSON.parse(localStorage.getItem('analytics-store'));
  const state = raw.state || raw;
  const w = (state.dashboardWidgets || []).find(x => x.title === '各机构本年投放金额排名');
  if (!w) return null;
  const vals = w.data.map(r => ({j: r.jgmc, v: r.je}));
